const fs=require('fs');
const lines=fs.readFileSync('data/steam.csv','utf8').split(/\r?\n/).filter(Boolean);
const hdr=lines[0].split(',');
function parseLine(l){ // naive split is unsafe for quoted commas; data fields here are mostly safe except name. Use a small CSV parser.
  const out=[];let cur='',q=false;
  for(const ch of l){ if(ch==='"'){q=!q;} else if(ch===','&&!q){out.push(cur);cur='';} else cur+=ch;}
  out.push(cur);return out;
}
const idx={};hdr.forEach((h,i)=>idx[h]=i);
const mid=s=>{const m=s.split('-');return m.length===2?(+m[0]+ +m[1])/2:0;};
let rows=[];
for(let i=1;i<lines.length;i++){
  const c=parseLine(lines[i]);
  const pos=+c[idx.positive_ratings],neg=+c[idx.negative_ratings];
  const own=mid(c[idx.owners]),price=+c[idx.price],pt=+c[idx.average_playtime];
  if([pos,neg,price,pt].some(Number.isNaN))continue;
  const tot=pos+neg;
  rows.push({name:c[idx.name],pos,neg,own,price,pt,tot,ratio:tot>0?pos/tot:0,rev:own*price});
}
const n=rows.length;
const mean=a=>a.reduce((x,y)=>x+y,0)/a.length;
const corr=(a,b)=>{const ma=mean(a),mb=mean(b);let cov=0,va=0,vb=0;for(let i=0;i<a.length;i++){cov+=(a[i]-ma)*(b[i]-mb);va+=(a[i]-ma)**2;vb+=(b[i]-mb)**2;}return cov/Math.sqrt(va*vb);};
const col=k=>rows.map(r=>r[k]);
const med=a=>{const s=[...a].sort((x,y)=>x-y);return s[Math.floor(s.length/2)];};
console.log('games parsed:',n);
console.log('median total ratings:',med(col('tot')));
console.log('mean positive ratio:',mean(col('ratio')).toFixed(3));
console.log('\nCorrelations (Pearson):');
console.log('  owners vs positive-ratio :',corr(col('own'),col('ratio')).toFixed(3));
console.log('  owners vs total-ratings  :',corr(col('own'),col('tot')).toFixed(3));
console.log('  owners vs revenue        :',corr(col('own'),col('rev')).toFixed(3));
console.log('  positive-ratio vs playtime:',corr(col('ratio'),col('pt')).toFixed(3));
console.log('  revenue vs positive-ratio:',corr(col('rev'),col('ratio')).toFixed(3));
const top=(k,label,kk=8,filter=r=>true)=>{
  console.log(`\n--- Top ${kk} by ${label} ---`);
  rows.filter(filter).sort((a,b)=>b[k]-a[k]).slice(0,kk).forEach(r=>
    console.log(`  ${r.name.slice(0,32).padEnd(32)} own=${String(Math.round(r.own)).padStart(10)} ratio=${r.ratio.toFixed(2)} rev=${String(Math.round(r.rev)).padStart(11)} tot=${r.tot}`));
};
top('own','Owners (reach)');
top('rev','Revenue proxy (owners*price)');
top('ratio','Positive ratio (>=500 ratings)',8,r=>r.tot>=500);
EOF
